package io.aetheris.orchestrator.api;import io.aetheris.orchestrator.career.*;import io.aetheris.orchestrator.stage9.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/orchestrator/stage9/boundaries") public class Stage9BoundaryController {private final GitHubCareerEvidenceService career;private final Stage9OwnerPolicyService policy;public Stage9BoundaryController(GitHubCareerEvidenceService career,Stage9OwnerPolicyService policy){this.career=career;this.policy=policy;}@GetMapping("/speech") public LocalSpeechRuntimePlan speech(){return LocalSpeechRuntimePlan.current();}@GetMapping("/remote-transport") public PrivateRemoteTransportPlan remote(){return PrivateRemoteTransportPlan.current();}@GetMapping("/windows-host") public WindowsHostDaemonPlan windows(){return WindowsHostDaemonPlan.current();}@GetMapping("/public-profiles") public PublicProfileConnectorPlan profiles(){return PublicProfileConnectorPlan.current();}@GetMapping("/owner-policy") public List<CapabilityPolicyEntry> policy(){return policy.entries();}@PostMapping("/career/github-evidence") public GitHubCareerEvidenceResult github(@RequestBody GitHubCareerEvidenceRequest r){return career.inspect(r);}}
